package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.POJOPropertyBuilder;
import com.fasterxml.jackson.databind.util.BeanUtil;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class POJOPropertiesCollector__addInjectables_TriageGen2Test {

    private POJOPropertiesCollector collector;
    private MapperConfig<?> mockConfig;
    private JavaType mockType;
    private AnnotatedClass mockClassDef;
    private AnnotationIntrospector mockAi;
    private Map<String, POJOPropertyBuilder> props;

    // Subclass to expose protected method and allow mocking of internal state
    private static class TestablePOJOPropertiesCollector extends POJOPropertiesCollector {
        protected TestablePOJOPropertiesCollector(MapperConfig<?> config, boolean forSerialization, JavaType type, AnnotatedClass classDef, String mutatorPrefix) {
            super(config, forSerialization, type, classDef, mutatorPrefix);
        }

        @Override
        public void _addInjectables(Map<String, POJOPropertyBuilder> props) {
            super._addInjectables(props);
        }

        // Override to spy on the internal call
        @Override
        protected void _doAddInjectable(Object id, AnnotatedMember m) {
            super._doAddInjectable(id, m);
        }
    }

    @Before
    public void setUp() {
        mockConfig = mock(MapperConfig.class);
        mockType = mock(JavaType.class);
        mockClassDef = mock(AnnotatedClass.class);
        mockAi = mock(AnnotationIntrospector.class);
        props = new HashMap<>();

        // We create a spy of the collector to verify _doAddInjectable calls
        collector = spy(new TestablePOJOPropertiesCollector(mockConfig, true, mockType, mockClassDef, "set"));

        // Use reflection to set the private/protected _annotationIntrospector field if necessary, 
        // but since we can't easily access private fields in a clean way without reflection, 
        // we assume the collector is initialized with the AI via the constructor or internal logic.
        // However, since the provided code uses _annotationIntrospector, we must ensure it's set.
        try {
            java.lang.reflect.Field aiField = POJOPropertiesCollector.class.getDeclaredField("_annotationIntrospector");
            aiField.setAccessible(true);
            aiField.set(collector, mockAi);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testAddInjectables_NullAi() {
        try {
            java.lang.reflect.Field aiField = POJOPropertiesCollector.class.getDeclaredField("_annotationIntrospector");
            aiField.setAccessible(true);
            aiField.set(collector, null);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        collector._addInjectables(props);

        // Verify no interaction with classDef because it returns early
        verifyNoInteractions(mockClassDef);
    }

    @Test
    public void testAddInjectables_WithFieldsAndMethods() {
        // Setup Fields
        AnnotatedField mockField = mock(AnnotatedField.class);
        Object fieldId = "fieldId";
        when(mockClassDef.fields()).thenReturn(java.util.Collections.singletonList(mockField));
        when(mockAi.findInjectableValueId(mockField)).thenReturn(fieldId);

        // Setup Methods
        // 1. A method with 1 parameter (should be included)
        AnnotatedMethod validMethod = mock(AnnotatedMethod.class);
        Object methodId = "methodId";
        when(validMethod.getParameterCount()).thenReturn(1);

        // 2. A method with 0 parameters (should be skipped)
        AnnotatedMethod invalidMethod = mock(AnnotatedMethod.class);
        when(invalidMethod.getParameterCount()).thenReturn(0);

        // 3. A method with 2 parameters (should be skipped)
        AnnotatedMethod tooManyParamsMethod = mock(AnnotatedMethod.class);
        when(tooManyParamsMethod.getParameterCount()).thenReturn(2);

        when(mockClassDef.memberMethods()).thenReturn(java.util.Arrays.asList(validMethod, invalidMethod, tooManyParamsMethod));
        when(mockAi.findInjectableValueId(validMethod)).thenReturn(methodId);

        // Execute
        collector._addInjectables(props);

        // Verify
        // Should call _doAddInjectable for the field
        verify(collector)._doAddInjectable(eq(fieldId), eq(mockField));
        // Should call _doAddInjectable for the valid method
        verify(collector)._doAddInjectable(eq(methodId), eq(validMethod));
        // Should NOT call for invalid methods
        verify(collector, never())._doAddInjectable(any(), eq(invalidMethod));
        verify(collector, never())._doAddInjectable(any(), eq(tooManyParamsMethod));
    }

    @Test
    public void testAddInjectables_NoFieldsNoMethods() {
        when(mockClassDef.fields()).thenReturn(java.util.Collections.emptyList());
        when(mockClassDef.memberMethods()).thenReturn(java.util.Collections.emptyList());

        collector._addInjectables(props);

        verify(collector, never())._doAddInjectable(any(), any());
    }
}
